<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { createApiToken, fetchApiTokens, getApiErrorMessage, revokeApiToken, rotateApiToken, type ApiTokenView, type CreatedApiToken } from '../api/http'
import { formatLocalDateTime, hasTextWithin } from '../utils/format'
const router = useRouter(); const tokens = ref<ApiTokenView[]>([]); const name = ref(''); const permission = ref<'READ' | 'READ_WRITE'>('READ'); const expiresAt = ref(''); const loading = ref(true); const saving = ref(false); const error = ref(''); const revealed = ref<CreatedApiToken | null>(null); const confirming = ref<string | null>(null)
const minimumExpiry = new Date(Date.now() + 60_000).toISOString().slice(0, 16)
async function loadTokens() { loading.value = true; error.value = ''; try { tokens.value = await fetchApiTokens() } catch (requestError: unknown) { error.value = getApiErrorMessage(requestError, '无法加载 API Token。') } finally { loading.value = false } }
async function refreshAfterMutation(successMessage: string) { try { tokens.value = await fetchApiTokens() } catch (requestError: unknown) { if (tokens.value.length === 0) error.value = `${successMessage}，但列表刷新失败：${getApiErrorMessage(requestError, '请点击重试。')}` } }
onMounted(() => { void loadTokens() })
async function create() { if (!hasTextWithin(name.value, 1, 64)) { error.value = 'Token 名称长度必须为 1-64 个字符。'; return } if (expiresAt.value && new Date(expiresAt.value).getTime() <= Date.now()) { error.value = '过期时间必须晚于当前时间。'; return } saving.value = true; error.value = ''; try { revealed.value = await createApiToken({ name: name.value.trim(), permission: permission.value, ...(expiresAt.value ? { expiresAt: new Date(expiresAt.value).toISOString() } : {}) }); await refreshAfterMutation('Token 创建成功'); name.value = ''; expiresAt.value = '' } catch (requestError: unknown) { error.value = getApiErrorMessage(requestError, 'Token 创建失败。') } finally { saving.value = false } }
async function rotate(id: number) { const key = `rotate:${id}`; if (confirming.value !== key) { confirming.value = key; return } confirming.value = null; saving.value = true; error.value = ''; try { revealed.value = await rotateApiToken(id); await refreshAfterMutation('Token 轮换成功') } catch (requestError: unknown) { error.value = getApiErrorMessage(requestError, 'Token 轮换失败。') } finally { saving.value = false } }
async function revoke(id: number) { const key = `revoke:${id}`; if (confirming.value !== key) { confirming.value = key; return } confirming.value = null; saving.value = true; error.value = ''; try { await revokeApiToken(id); await refreshAfterMutation('Token 撤销成功') } catch (requestError: unknown) { error.value = getApiErrorMessage(requestError, 'Token 撤销失败。') } finally { saving.value = false } }
</script>
<template><main class="form-page"><button class="back-link" @click="router.push('/')">← 返回反馈列表</button><section class="form-panel token-panel"><p class="eyebrow">API ACCESS</p><h1>API Token</h1><p class="form-lede">Token 只在创建或轮换后显示一次，请立即保存。</p><div v-if="revealed" class="token-reveal"><strong>新的 Token</strong><code>{{ revealed.token }}</code><button class="secondary-button" type="button" @click="revealed = null">我已保存</button></div><form class="token-create-form" @submit.prevent="create"><label>名称<input v-model="name" maxlength="64" placeholder="例如：自动化脚本" /></label><label>过期时间<input v-model="expiresAt" type="datetime-local" :min="minimumExpiry" /></label><fieldset class="permission-control"><legend>权限</legend><button type="button" :class="{ active: permission === 'READ' }" @click="permission = 'READ'">只读</button><button type="button" :class="{ active: permission === 'READ_WRITE' }" @click="permission = 'READ_WRITE'">读写</button></fieldset><button class="primary-button" type="submit" :disabled="saving">{{ saving ? '处理中…' : '创建 Token' }}</button></form><p v-if="loading" class="list-status">正在加载 Token…</p><p v-else-if="error && tokens.length === 0" class="list-status warning">{{ error }} <button type="button" class="inline-action" @click="loadTokens">重试</button></p><p v-else-if="error" class="list-status warning">{{ error }} <button type="button" class="inline-action" @click="loadTokens">重试</button></p><div v-else class="token-list"><div v-for="token in tokens" :key="token.id" class="token-row"><div><strong>{{ token.name }}</strong><small>{{ token.scopes }} · 创建于 {{ formatLocalDateTime(token.createdAt) }} · {{ token.lastUsedAt ? `最后使用于 ${formatLocalDateTime(token.lastUsedAt)}` : '尚未使用' }} · {{ token.revokedAt ? '已撤销' : token.expiresAt ? `过期于 ${formatLocalDateTime(token.expiresAt)}` : '永不过期' }}</small></div><div class="token-actions"><template v-if="confirming === `rotate:${token.id}`"><span class="token-confirm-label">确认轮换？</span><button type="button" :disabled="saving" @click="rotate(token.id)">确认</button><button type="button" :disabled="saving" @click="confirming = null">取消</button></template><template v-else-if="confirming === `revoke:${token.id}`"><span class="token-confirm-label">确认撤销？</span><button type="button" :disabled="saving" @click="revoke(token.id)">确认</button><button type="button" :disabled="saving" @click="confirming = null">取消</button></template><template v-else><button type="button" :disabled="saving || Boolean(token.revokedAt) || Boolean(token.expiresAt && new Date(token.expiresAt).getTime() <= Date.now())" @click="rotate(token.id)">{{ token.expiresAt && new Date(token.expiresAt).getTime() <= Date.now() ? '已过期' : '轮换' }}</button><button type="button" :disabled="saving || Boolean(token.revokedAt)" @click="revoke(token.id)">撤销</button></template></div></div><p v-if="tokens.length === 0" class="no-comments">暂无 API Token。</p></div></section></main></template>
